export interface CreateDubbingJobData {
    /** Unique identifier for the created dubbing job. */
    job_id: string;
    /** Short-lived signed URL. `PUT` the raw media bytes here with headers `Content-Type: <mime>` and `x-ms-blob-type: BlockBlob` before starting the job. */
    upload_url?: string | undefined;
    /** Signed URL to upload a source SRT file, when applicable. */
    srt_upload_url?: string | undefined;
    /** How long the signed upload URL(s) remain valid, in hours. */
    expires_in_hours?: number | undefined;
    /** Whether processing has already begun for this job. */
    processing_started: boolean;
    voice_cloning: boolean;
    voice_id?: string | undefined;
    pace_preset?: string | undefined;
    /** Echo of the requested quality tier (`plus`/`lite`), or null when the service default was used. */
    model_tier?: string | undefined;
}
